#include "live_command_renderer.hpp"
#include "gl_viewport.hpp"
#include <QApplication>
#include <QTimer>
#include <QElapsedTimer>
#include <QSurfaceFormat>
#include <QJsonDocument>
#include <QJsonArray>
#include <QJsonObject>
#include <QFile>
#include <algorithm>
#include <cstdio>
struct PaintCounter:QObject {unsigned paints=0;bool eventFilter(QObject*,QEvent* e) override {if(e->type()==QEvent::Paint)++paints;return false;}};
int main(int argc,char**argv){
 if(argc!=4)return 2;
 QSurfaceFormat f;f.setVersion(3,3);f.setProfile(QSurfaceFormat::CoreProfile);QSurfaceFormat::setDefaultFormat(f);
 QApplication app(argc,argv);GlViewport view;view.resize(800,600);view.show();app.processEvents();
 LiveCommandRenderer live(view);if(!view.ready() || !live.open(argv[1]))return 3;
 PaintCounter paints;view.installEventFilter(&paints);QElapsedTimer elapsed;elapsed.start();QJsonArray frames,polls;
 live.framePresented=[&]{frames.append(elapsed.nsecsElapsed()/1e6);};
 QTimer timer;timer.setSingleShot(true);bool refused=false;QString error;
 QObject::connect(&timer,&QTimer::timeout,[&]{
  auto before=elapsed.nsecsElapsed();auto commands=live.result()?live.result()->commands:0;auto presents=live.presentations();
  bool ok=live.poll();auto after=elapsed.nsecsElapsed();
  auto n=live.result()?live.result()->commands:0;
  polls.append(QJsonObject{{"at_ms",before/1e6},{"duration_ms",(after-before)/1e6},{"commands",int(n-commands)},{"presents",int(live.presentations()-presents)},{"pending",live.hasPendingCommands()}});
  if(!ok || live.ended() || elapsed.elapsed()>std::atoi(argv[3])*1000){refused=!ok;error=live.error();app.quit();return;}
  timer.start(live.hasPendingCommands()?0:16);
 });
 timer.start(0);QFile ready(QString(argv[2])+".ready");ready.open(QIODevice::WriteOnly);ready.close();app.exec();
 QJsonObject report{{"scope","Real command consumer, no diagnostic readbacks; isolated Xvfb"},{"elapsed_ms",elapsed.nsecsElapsed()/1e6},{"refused",refused},{"error",error},{"ended",live.ended()},{"frames_ms",frames},{"polls",polls},{"paints",int(paints.paints)},{"viewport_uploads",qint64(view.imageUploads())}};
 if(auto r=live.result()){report["commands"]=int(r->commands);report["presentations"]=int(r->presents);report["renderer"]=QString::fromStdString(r->driver.renderer);report["vendor"]=QString::fromStdString(r->driver.vendor);report["uploads"]=qint64(r->stats.uploads);report["copies"]=qint64(r->stats.copies);report["native_readbacks"]=qint64(r->stats.nativeReadbacks);report["rgba_readbacks"]=qint64(r->stats.rgbaReadbacks);}
 QFile out(argv[2]);out.open(QIODevice::WriteOnly);out.write(QJsonDocument(report).toJson());return 0;
}
